// ==========================================
// 1. CUSTOM FILE PERSISTENCE
// ==========================================
function loadCustomFilesFromStorage() {
  try {
    const custom = JSON.parse(localStorage.getItem('gsm_custom_files')) || [];
    if (custom.length > 0) {
      custom.forEach(item => {
        if (!MEGA_DB.some(x => x.id === item.id)) {
          MEGA_DB.unshift(item);
        }
      });
    }
  } catch (e) {
    console.error('Error loading custom files:', e);
  }
}

// ==========================================
// 2. MULTI-PAGE NAVIGATION ROUTER
// ==========================================
// ================= PAGE & ROUTE PROTECTION =================
function navigateTo(pageId) {
  const user = getCurrentUser();
  const isAdmin = Boolean(user && user.role === 'admin');

  // 1. Strict Protection for Admin Route
  if (pageId === 'admin' || pageId === 'admin-panel') {
    if (!user) {
      showToast('Access Denied: Please sign in with an Administrator account.');
      openAuthModal('login', 'Administrator Access Required: Sign in to view Admin Console.');
      window.location.hash = '#home';
      return;
    }
    if (!isAdmin) {
      showToast('Access Denied: Administrator privileges required.');
      navigateTo('home');
      return;
    }
  }

  // 2. Protection for Authenticated Workshop Utility Routes
  if (pageId === 'flashing-tools' || pageId === 'frp-bypass') {
    if (!user) {
      showToast('Technician Sign In Required to access workshop flashing utilities.');
      openAuthModal('login', 'Technician Session Required: Please sign in to access tools.');
      window.location.hash = '#home';
      return;
    }
  }

  activePage = pageId;

  document.querySelectorAll('.page-view').forEach(p => p.classList.remove('active'));
  const target = document.getElementById('view-' + pageId);
  if (target) target.classList.add('active');

  // Update navbar styling while strictly enforcing visibility
  document.querySelectorAll('.nav-tab').forEach(tab => {
    const isSpecialAdmin = tab.classList.contains('admin-only');
    const isAuthOnly = tab.classList.contains('auth-only');

    if (isSpecialAdmin) {
      tab.className = 'nav-tab admin-only px-2.5 py-1.5 text-xs font-bold rounded-xl text-amber-300 bg-gradient-to-r from-amber-500/15 via-yellow-500/10 to-amber-600/15 border border-amber-500/40 hover:border-amber-400 hover:from-amber-500/25 transition-all flex items-center space-x-1.5 group ' + (isAdmin ? '' : 'hidden');
    } else if (isAuthOnly) {
      tab.className = 'nav-tab auth-only px-2.5 py-1.5 text-xs font-semibold rounded-xl text-slate-300 hover:text-white hover:bg-slate-900/80 transition-all flex items-center space-x-1.5 ' + (user ? '' : 'hidden');
    } else {
      tab.className = 'nav-tab px-2.5 py-1.5 text-xs font-semibold rounded-xl text-slate-300 hover:text-white hover:bg-slate-900/80 transition-all flex items-center space-x-1.5';
    }
  });
  
  const activeNav = document.getElementById('nav-' + pageId);
  if (activeNav) {
    if (pageId === 'admin') {
      if (isAdmin) {
        activeNav.className = 'nav-tab admin-only px-2.5 py-1.5 text-xs font-black rounded-xl text-amber-200 bg-gradient-to-r from-amber-500/30 via-yellow-500/20 to-amber-600/30 border border-amber-400 shadow-lg shadow-amber-500/20 transition-all flex items-center space-x-1.5 ring-1 ring-amber-400/50';
      } else {
        activeNav.className = 'nav-tab admin-only hidden';
      }
    } else {
      activeNav.className = 'nav-tab px-2.5 py-1.5 text-xs font-bold rounded-xl text-cyan-300 bg-cyan-500/15 border border-cyan-500/50 shadow-sm shadow-cyan-500/15 transition-all flex items-center space-x-1.5 ring-1 ring-cyan-500/30';
    }
  }

  // Enforce mobile & global visibility
  document.querySelectorAll('.admin-only').forEach(el => {
    if (isAdmin) el.classList.remove('hidden');
    else el.classList.add('hidden');
  });

  document.querySelectorAll('.auth-only').forEach(el => {
    if (user) el.classList.remove('hidden');
    else el.classList.add('hidden');
  });

  // Trigger page-specific initializers
  if (pageId === 'home') {
    renderHomeFeatured();
  } else if (pageId === 'flash-files') {
    renderCatalogPage();
    checkAndApplyAutoFilter();
  } else if (pageId === 'flashing-tools') {
    renderProcessorTools('mtk');
  } else if (pageId === 'frp-bypass') {
    renderFrpTools();
    renderTestPoints();
  } else if (pageId === 'video-tutorials') {
    renderVideoCatalog();
  } else if (pageId === 'admin') {
    renderAdminDashboard();
  } else if (pageId === 'testpoints') {
    renderTestPointsCatalog();
  }

  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function renderAdminDashboard() {
  const users = getUsersDb();
  const statUsers = document.getElementById('admin-stat-users');
  if (statUsers) statUsers.textContent = users.length;
  const statFiles = document.getElementById('admin-stat-files');
  if (statFiles) statFiles.textContent = MEGA_DB.length;

  const tbody = document.getElementById('admin-users-table-body');
  if (!tbody) return;

  tbody.innerHTML = users.map(u => `
    <tr class="hover:bg-slate-850/60 transition-colors">
      <td class="py-3 px-4 font-bold text-white">${u.name}</td>
      <td class="py-3 px-4 font-mono text-cyan-400 font-bold">${u.username}</td>
      <td class="py-3 px-4 text-slate-300">${u.email}</td>
      <td class="py-3 px-4 text-slate-400">${u.shop || 'Workshop'}</td>
      <td class="py-3 px-4">
        <span class="px-2 py-0.5 rounded text-[10px] font-mono font-bold ${u.role === 'admin' ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30' : 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30'}">
          ${u.role === 'admin' ? 'MASTER ADMIN' : 'TECHNICIAN'}
        </span>
      </td>
      <td class="py-3 px-4 font-mono text-slate-500 text-[11px]">${u.registeredAt ? u.registeredAt.split('T')[0] : '2026-01-01'}</td>
    </tr>
  `).join('');
}

function openTab(tabName) {
  if (tabName === 'drivers') navigateTo('drivers');
  else if (tabName === 'tools') navigateTo('flashing-tools');
  else if (tabName === 'firmware' || tabName === 'files') navigateTo('flash-files');
  else if (tabName === 'frp') navigateTo('frp-bypass');
  else if (tabName === 'videos') navigateTo('video-tutorials');
  else navigateTo(tabName);
}

// ==========================================
// 3. AUTHENTICATION & TECHNICIAN USER SYSTEM
// ==========================================
let USERS_DB_CACHE = null;

function getNormalizedUser(u) {
  const email = (u.email || '').trim().toLowerCase();
  const uname = (u.username || (email ? email.split('@')[0] : '') || '').trim().toLowerCase();
  const password = u.password || u.pass || '';
  return {
    id: u.id || ('tech_' + Math.random().toString(36).substring(2, 9)),
    name: u.name || 'Technician',
    username: uname,
    email: email,
    pass: password,
    password: password,
    shop: u.shop || 'Independent Repair Lab',
    role: u.role || 'technician',
    isVip: Boolean(u.isVip || u.role === 'admin'),
    registeredAt: u.registeredAt || new Date().toISOString()
  };
}

function initUsersDb() {
  let existing = null;
  try {
    existing = localStorage.getItem('gsm_users_db') || localStorage.getItem('gsm_users_database');
  } catch(e) {
    console.warn('localStorage not accessible', e);
  }

  let users = [];
  if (existing) {
    try {
      users = JSON.parse(existing);
      if (!Array.isArray(users)) users = [];
    } catch(e) {
      users = [];
    }
  }

  const defaultAdmin = {
    id: 'user_bhuwan',
    email: 'bhuwan@bastola.com.np',
    username: 'bhuwan',
    name: 'Bhuwan Bastola',
    shop: 'Gopal Electronics (Surkhet)',
    pass: 'password123',
    password: 'password123',
    role: 'admin',
    isVip: true,
    registeredAt: '2026-01-01T00:00:00Z'
  };

  const defaultTech = {
    id: 'user_demo',
    email: 'demo@gsmhub.com',
    username: 'demo',
    name: 'Workshop Technician',
    shop: 'Nepal Mobile Lab',
    pass: 'tech123',
    password: 'tech123',
    role: 'technician',
    isVip: false,
    registeredAt: '2026-02-15T00:00:00Z'
  };

  users = users.map(getNormalizedUser);

  if (!users.some(u => u.email === defaultAdmin.email || u.username === defaultAdmin.username)) {
    users.unshift(defaultAdmin);
  }
  if (!users.some(u => u.email === defaultTech.email || u.username === defaultTech.username)) {
    users.push(defaultTech);
  }

  USERS_DB_CACHE = users;
  try {
    localStorage.setItem('gsm_users_db', JSON.stringify(users));
    localStorage.setItem('gsm_users_database', JSON.stringify(users));
  } catch(e) {}

  updateDbUserCountBadge();
  return users;
}

function getUsersDb() {
  if (USERS_DB_CACHE && Array.isArray(USERS_DB_CACHE) && USERS_DB_CACHE.length > 0) {
    return USERS_DB_CACHE;
  }
  let users = [];
  try {
    const raw = localStorage.getItem('gsm_users_db') || localStorage.getItem('gsm_users_database');
    if (raw) users = JSON.parse(raw);
  } catch(e) {}
  if (!Array.isArray(users) || users.length === 0) {
    users = initUsersDb();
  } else {
    users = users.map(getNormalizedUser);
    USERS_DB_CACHE = users;
  }
  return users;
}

function saveUsersDb(users) {
  const normalized = users.map(getNormalizedUser);
  USERS_DB_CACHE = normalized;
  try {
    localStorage.setItem('gsm_users_db', JSON.stringify(normalized));
    localStorage.setItem('gsm_users_database', JSON.stringify(normalized));
  } catch(e) {}
  updateDbUserCountBadge();
}

function updateDbUserCountBadge() {
  const badge = document.getElementById('db-user-count');
  if (badge) {
    const count = USERS_DB_CACHE ? USERS_DB_CACHE.length : 2;
    badge.textContent = count;
  }
}

function initAuthSession() {
  initUsersDb();
  currentUser = getCurrentUser();
  renderAuthNav();
}

function getCurrentUser() {
  try {
    const saved = localStorage.getItem('gsm_current_user');
    if (saved) return getNormalizedUser(JSON.parse(saved));
  } catch (e) {}
  return null;
}

