function openAuthModal(tab = "login", msg = null) {
  const modal = document.getElementById("auth-modal");
  if (!modal) return;
  modal.classList.remove("hidden");

  const contextMsg = document.getElementById("auth-context-msg");
  if (contextMsg) {
    if (msg) {
      contextMsg.textContent = msg;
      contextMsg.classList.remove("hidden");
    } else {
      contextMsg.classList.add("hidden");
    }
  }

  switchAuthTab(tab);
}

function closeAuthModal() {
  const modal = document.getElementById("auth-modal");
  if (modal) modal.classList.add("hidden");
  const errLogin = document.getElementById("login-error-msg");
  if (errLogin) errLogin.classList.add("hidden");
  const errReg = document.getElementById("reg-error-msg");
  if (errReg) errReg.classList.add("hidden");
}

function switchAuthTab(tab) {
  const loginTabBtn = document.getElementById("auth-tab-login");
  const regTabBtn = document.getElementById("auth-tab-register");
  const dbTabBtn = document.getElementById("auth-tab-db");
  const loginForm = document.getElementById("login-form");
  const regForm = document.getElementById("register-form");
  const dbView = document.getElementById("auth-db-view");
  const title = document.getElementById("auth-modal-title");
  const subtitle = document.getElementById("auth-modal-subtitle");

  const errLogin = document.getElementById("login-error-msg");
  if (errLogin) errLogin.classList.add("hidden");
  const errReg = document.getElementById("reg-error-msg");
  if (errReg) errReg.classList.add("hidden");

  const user = getCurrentUser();

  if (tab === "login") {
    if (loginTabBtn) loginTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-cyan-400 text-cyan-400 text-center transition-colors";
    if (regTabBtn) regTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (dbTabBtn) dbTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (loginForm) loginForm.classList.remove("hidden");
    if (regForm) regForm.classList.add("hidden");
    if (dbView) dbView.classList.add("hidden");
    if (title) title.textContent = "Technician Portal Sign In";
    if (subtitle) subtitle.textContent = "Enter your Technician ID or Email and password";
  } else if (tab === "register") {
    if (regTabBtn) regTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-emerald-400 text-emerald-400 text-center transition-colors";
    if (loginTabBtn) loginTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (dbTabBtn) dbTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (regForm) regForm.classList.remove("hidden");
    if (loginForm) loginForm.classList.add("hidden");
    if (dbView) dbView.classList.add("hidden");
    if (title) title.textContent = "Register New Technician Account";
    if (subtitle) subtitle.textContent = "Create your verified account for instant file downloads";
  } else if (tab === "db") {
    if (!user || user.role !== "admin") {
      showToast("Administrator privileges required to view database records.");
      switchAuthTab("login");
      return;
    }
    if (dbTabBtn) dbTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-purple-400 text-purple-400 text-center transition-colors";
    if (loginTabBtn) loginTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (regTabBtn) regTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (dbView) dbView.classList.remove("hidden");
    if (loginForm) loginForm.classList.add("hidden");
    if (regForm) regForm.classList.add("hidden");
    if (title) title.textContent = "Technician User Database";
    if (subtitle) subtitle.textContent = "Master Administrator view of stored technician accounts";
    renderUsersDbList();
  }
}

function handleLoginSubmit(e) {
  if (e) e.preventDefault();
  const emailInput = document.getElementById("login-email");
  const passInput = document.getElementById("login-password");
  const errMsg = document.getElementById("login-error-msg");

  const query = emailInput ? emailInput.value.trim().toLowerCase() : "";
  const pass = passInput ? passInput.value.trim() : "";

  if (!query || !pass) {
    if (errMsg) {
      errMsg.textContent = "Please provide both username/email and password.";
      errMsg.classList.remove("hidden");
    }
    return;
  }

  const users = getUsersDb();
  const found = users.find(u => {
    const matchId = (u.email && u.email.toLowerCase() === query) ||
                    (u.username && u.username.toLowerCase() === query) ||
                    (u.name && u.name.toLowerCase() === query);
    const matchPass = (u.pass === pass || u.password === pass);
    return matchId && matchPass;
  });

  if (found) {
    currentUser = found;
    localStorage.setItem("gsm_current_user", JSON.stringify(found));
    closeAuthModal();
    renderAuthNav();
    showToast(`Welcome back, ${found.name}! (${found.shop || "Lab"})`);
    if (selectedFileForDownload) {
      const fileId = selectedFileForDownload;
      showToast(`Login verified! Opening 5-second download gateway...`);
      setTimeout(() => {
        initiateFileDownload(fileId);
      }, 300);
    }
  } else {
    if (errMsg) {
      errMsg.textContent = "Invalid credentials. Please verify your Technician ID/email and password, or create an account.";
      errMsg.classList.remove("hidden");
    }
  }
}

function handleRegisterSubmit(e) {
  if (e) e.preventDefault();
  const nameInput = document.getElementById("reg-name");
  const unameInput = document.getElementById("reg-username");
  const shopInput = document.getElementById("reg-shop");
  const emailInput = document.getElementById("reg-email");
  const passInput = document.getElementById("reg-password");
  const errMsg = document.getElementById("reg-error-msg");

  const name = nameInput ? nameInput.value.trim() : "";
  const email = emailInput ? emailInput.value.trim().toLowerCase() : "";
  let uname = unameInput ? unameInput.value.trim().toLowerCase() : "";
  if (!uname && email) {
    uname = email.split("@")[0];
  }
  const shop = shopInput ? shopInput.value.trim() : "";
  const pass = passInput ? passInput.value.trim() : "";

  if (!name || !email || !pass) {
    if (errMsg) {
      errMsg.textContent = "Full name, email address, and password are required.";
      errMsg.classList.remove("hidden");
    }
    return;
  }

  const users = getUsersDb();
  if (users.some(u => (u.email && u.email.toLowerCase() === email) || (u.username && u.username.toLowerCase() === uname))) {
    if (errMsg) {
      errMsg.textContent = `An account with email (${email}) or username (${uname}) is already registered! Please sign in.`;
      errMsg.classList.remove("hidden");
    }
    return;
  }

  const newUser = {
    id: "tech_" + Date.now(),
    name: name,
    username: uname,
    email: email,
    pass: pass,
    password: pass,
    shop: shop || "Independent Repair Lab",
    role: "technician",
    isVip: false,
    registeredAt: new Date().toISOString()
  };

  users.push(newUser);
  saveUsersDb(users);
  currentUser = newUser;
  localStorage.setItem("gsm_current_user", JSON.stringify(newUser));
  closeAuthModal();
  renderAuthNav();
  showToast(`Account successfully registered & saved to database! Welcome, ${newUser.name}!`);

  if (selectedFileForDownload) {
    const fileId = selectedFileForDownload;
    showToast(`Registration verified! Opening 5-second download gateway...`);
    setTimeout(() => {
      initiateFileDownload(fileId);
    }, 300);
  }
}

function exportUsersDbJson() {
  const users = getUsersDb();
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(users, null, 2));
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute("href", dataStr);
  downloadAnchor.setAttribute("download", "gsm_users_database.json");
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();
  showToast("Database backup downloaded!");
}

function resetUsersDbToDefaults() {
  localStorage.removeItem('gsm_users_db');
  localStorage.removeItem('gsm_users_database');
  USERS_DB_CACHE = null;
  initUsersDb();
  renderUsersDbList();
  renderAuthNav();
  showToast("Database reset to factory default accounts.");
}

function quickFillAndLogin(email, pass) {
  const emailInput = document.getElementById('login-email');
  const passInput = document.getElementById('login-password');
  if (emailInput) emailInput.value = email;
  if (passInput) passInput.value = pass;
  switchAuthTab('login');
  handleLoginSubmit(null);
}

function handleLogout() {
  localStorage.removeItem('gsm_current_user');
  renderAuthNav();
  showToast('Logged out successfully.');
}

