// ================= AUTO-FILTER DETECTION BRIDGE =================
let isApplyingAutoFilter = false;

function checkAndApplyAutoFilter() {
  if (isApplyingAutoFilter) return false;
  
  let brandToFilter = null;

  // 1. Check URL query string or hash via robust Regex (Works on all browsers & file:// URLs)
  try {
    const fullHref = (window.location && window.location.href) || "";
    const m = /[?&](?:brand|filter)=([^&#]+)/i.exec(fullHref);
    if (m && m[1]) {
      brandToFilter = decodeURIComponent(m[1].replace(/\+/g, " "));
    }
  } catch(e) {}

  // 2. Check localStorage (persisted from WebUSB monitor or companion tools)
  if (!brandToFilter) {
    try {
      brandToFilter = localStorage.getItem("gsm_pending_filter");
      if (brandToFilter) {
        localStorage.removeItem("gsm_pending_filter");
      }
    } catch(e) {}
  }

  if (brandToFilter && brandToFilter !== "All") {
    isApplyingAutoFilter = true;
    try {
      console.log("Applying auto-filter for detected mobile device:", brandToFilter);
      setBrandFilter(brandToFilter);
      showToast(`USB Device Mode Recognized! Displaying ${brandToFilter} Flash Files`);
    } finally {
      isApplyingAutoFilter = false;
    }
    return true;
  }
  return false;
}

function setBrandFilter(brand) {
  catalogBrandFilter = brand;
  catalogSeriesFilter = 'All';
  catalogCurrentPage = 1;
  
  document.querySelectorAll('.brand-pill').forEach(pill => {
    const b = pill.getAttribute('data-brand');
    if (b === brand || (brand === 'Infinix & Tecno' && (b === 'Infinix' || b === 'Tecno'))) {
      pill.className = 'brand-pill active px-3 py-1.5 rounded-lg font-bold border border-cyan-500/40 bg-cyan-500/10 text-cyan-400 shrink-0';
    } else {
      pill.className = 'brand-pill px-3 py-1.5 rounded-lg font-medium border border-slate-800 bg-slate-900 text-slate-400 hover:text-white shrink-0';
    }
  });

  renderSubSeriesPills(brand === 'Infinix & Tecno' ? 'Infinix' : brand);
  renderCatalogPage();

  // If user is currently on home or any other page, navigate directly to flash-files!
  if (activePage !== 'flash-files') {
    navigateTo('flash-files');
  }

  // Smooth scroll to catalog section
  const target = document.getElementById('view-flash-files');
  if (target && typeof target.scrollIntoView === 'function') {
    target.scrollIntoView({ behavior: 'smooth' });
  }
}

