let videoProcessorFilter = 'all';
let activeVideo = VIDEO_TUTORIALS[0];

function setVideoProcessorFilter(proc) {
  videoProcessorFilter = proc;
  document.querySelectorAll('.video-proc-pill').forEach(btn => {
    const p = btn.getAttribute('data-proc');
    if (p === proc) {
      btn.className = 'video-proc-pill active px-3 py-1.5 rounded-lg text-xs font-bold border border-rose-500/40 bg-rose-500/15 text-rose-400 shrink-0 transition-all flex items-center space-x-1.5';
    } else {
      btn.className = 'video-proc-pill px-3 py-1.5 rounded-lg text-xs font-medium border border-slate-800 bg-slate-900 text-slate-400 hover:text-white shrink-0 transition-all flex items-center space-x-1.5';
    }
  });

  const filtered = getVideoTutorialsList();
  if (filtered.length > 0 && !filtered.some(v => v.id === activeVideo.id)) {
    activeVideo = filtered[0];
  }
  renderVideoCatalog();
}

function getVideoTutorialsList() {
  if (videoProcessorFilter === 'all') return VIDEO_TUTORIALS;
  return VIDEO_TUTORIALS.filter(v => v.processorCategory === videoProcessorFilter);
}

function renderVideoCatalog() {
  const container = document.getElementById('video-catalog-grid');
  if (!container) return;

  const filtered = getVideoTutorialsList();
  
  if (filtered.length === 0) {
    container.innerHTML = `<div class="col-span-full py-8 text-center text-xs text-slate-400 font-mono">No video tutorials found for this processor category.</div>`;
    return;
  }

  container.innerHTML = filtered.map((vid) => `
    <div onclick="selectVideoById('${vid.id}')" class="cursor-pointer bg-slate-900 border ${vid.id === activeVideo.id ? 'border-rose-500 ring-1 ring-rose-500' : 'border-slate-800 hover:border-slate-700'} rounded-xl p-3.5 transition-all group">
      <div class="relative aspect-video rounded-lg bg-slate-950 mb-2.5 overflow-hidden flex items-center justify-center">
        <div class="w-10 h-10 rounded-full bg-rose-500/20 border border-rose-500/50 flex items-center justify-center text-rose-400 group-hover:scale-110 transition-transform">
          <svg class="w-5 h-5 ml-0.5" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
        </div>
        <span class="absolute bottom-2 right-2 bg-slate-950/80 px-1.5 py-0.5 rounded text-[10px] font-mono text-slate-300">${vid.duration}</span>
        <span class="absolute top-2 left-2 bg-slate-950/90 border border-slate-700/80 px-1.5 py-0.5 rounded text-[9px] font-mono text-cyan-400 font-bold">${vid.processorName}</span>
      </div>
      <div class="flex items-center space-x-1.5 mb-1">
        <span class="text-[10px] font-mono font-bold text-rose-400 bg-rose-500/10 px-2 py-0.5 rounded">${vid.badge}</span>
      </div>
      <h4 class="text-xs font-bold text-white mt-1 line-clamp-1 group-hover:text-rose-400">${vid.title}</h4>
      <p class="text-[11px] text-slate-400 mt-0.5 line-clamp-2">${vid.desc}</p>
    </div>
  `).join('');

  updateActiveVideoPlayer();
}

function selectVideoById(vidId) {
  const found = VIDEO_TUTORIALS.find(v => v.id === vidId);
  if (found) {
    activeVideo = found;
    renderVideoCatalog();
    updateActiveVideoPlayer();
    const sec = document.getElementById('video-player-section');
    if (sec) sec.scrollIntoView({ behavior: 'smooth' });
  }
}

function selectVideoTutorial(idx) {
  if (VIDEO_TUTORIALS[idx]) {
    selectVideoById(VIDEO_TUTORIALS[idx].id);
  }
}

function updateActiveVideoPlayer() {
  if (!activeVideo) activeVideo = VIDEO_TUTORIALS[0];
  const iframe = document.getElementById('video-iframe');
  if (iframe) iframe.src = activeVideo.youtubeEmbed;
  const badge = document.getElementById('active-video-badge');
  if (badge) badge.textContent = `${activeVideo.processorName} • ${activeVideo.badge}`;
  const title = document.getElementById('active-video-title');
  if (title) title.textContent = activeVideo.title;
  const desc = document.getElementById('active-video-desc');
  if (desc) desc.textContent = activeVideo.desc;

  const stepsList = document.getElementById('active-video-steps');
  if (stepsList && activeVideo.steps) {
    stepsList.innerHTML = activeVideo.steps.map(s => `<li>${s}</li>`).join('');
  }
}

function downloadActiveVideoTools() {
  if (activeVideo && activeVideo.toolId) {
    initiateFileDownload(activeVideo.toolId);
  }
}

// ================= DOWNLOAD GATEKEEPER & MODAL =================
function initiateFileDownload(fileId) {
  const file = MEGA_DB.find(f => f.id === fileId) || MEGA_DB[0];
  selectedFileForDownload = file.id;

  currentUser = getCurrentUser();
  if (!currentUser) {
    openAuthModal('login', `Technician Login Required: Sign in to unlock automatic 5-second download for "${file.title}"`);
    return;
  }

  if (file.accessLevel === 'VIP' && !currentUser.isVip) {
    openVipComboModal();
    return;
  }

  openDownloadModal(file);
}

// ================= FIRMWARE DIRECT SOURCE RESOLVER & CREDITS =================
function getDirectSourceInfo(file) {
  if (!file) {
    return {
      provider: 'FirmwareFile.com',
      url: 'https://firmwarefile.com',
      badge: 'FirmwareFile ↗',
      label: 'Direct Source: FirmwareFile.com',
      credit: 'Multi-Brand Android Flash Files via FirmwareFile.com',
      color: 'emerald'
    };
  }

  if (file.brand === 'Samsung') {
    let code = (file.modelCode && file.modelCode !== 'Universal') ? file.modelCode.trim() : '';
    if (!code) {
      const m = (file.targetModel || '').match(/SM-[A-Z0-9]+/i);
      code = m ? m[0].toUpperCase() : 'SM-A546B';
    }
    return {
      provider: 'SamFw.com',
      url: `https://samfw.com/firmware/${encodeURIComponent(code)}`,
      badge: 'SamFw Direct ↗',
      label: `Official Direct Source: SamFw.com (${code})`,
      credit: `Official Samsung Factory 4-File Repair TAR via SamFw.com (${code})`,
      color: 'blue',
      modelCode: code
    };
  } else {
    let raw = (file.targetModel || file.title || '')
      .toLowerCase()
      .replace(/[\(\)\[\],&]/g, ' ')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-|-$/g, '');
    
    if (!raw || raw.length < 3) {
      raw = (file.brand || 'android').toLowerCase() + '-firmware';
    }

    return {
      provider: 'FirmwareFile.com',
      url: `https://firmwarefile.com/${encodeURIComponent(raw)}`,
      badge: 'FirmwareFile ↗',
      label: `Alternative Direct Source: FirmwareFile.com (${file.modelCode || file.targetModel})`,
      credit: `Direct Stock Firmware & Scatter Archive via FirmwareFile.com`,
      color: 'emerald',
      modelCode: file.modelCode || ''
    };
  }
}

function openDownloadModal(file) {
  const modal = document.getElementById('download-modal');
  document.getElementById('dl-modal-title').textContent = file.title;
  document.getElementById('dl-modal-desc').textContent = file.description;
  document.getElementById('dl-modal-size').textContent = file.fileSize;
  document.getElementById('dl-modal-chipset').textContent = file.chipset;
  document.getElementById('dl-modal-source').textContent = file.sourceName;
  document.getElementById('dl-modal-hash').textContent = file.checksum;

  const src = getDirectSourceInfo(file);
  const extBtn = document.getElementById('dl-external-source-btn');
  if (extBtn) {
    extBtn.href = src.url;
    document.getElementById('dl-external-source-name').textContent = `${src.provider} (${file.modelCode || file.targetModel})`;
    if (file.brand === 'Samsung') {
      extBtn.className = 'py-2.5 px-3 bg-blue-600/20 hover:bg-blue-600/30 text-blue-300 font-bold text-xs rounded-xl border border-blue-500/40 transition-all flex items-center justify-center space-x-2 shadow-sm';
    } else {
      extBtn.className = 'py-2.5 px-3 bg-emerald-600/20 hover:bg-emerald-600/30 text-emerald-300 font-bold text-xs rounded-xl border border-emerald-500/40 transition-all flex items-center justify-center space-x-2 shadow-sm';
    }
  }

  // Update Instant Direct Source Button (accessible without waiting 5s)
  const instantSrcBtn = document.getElementById('dl-instant-source-btn');
  const instantSrcLabel = document.getElementById('dl-instant-source-label');
  if (instantSrcBtn && instantSrcLabel) {
    instantSrcBtn.href = src.url;
    instantSrcLabel.textContent = src.label;
    if (file.brand === 'Samsung') {
      instantSrcBtn.className = 'w-full py-2.5 px-3 bg-gradient-to-r from-blue-600/20 via-blue-500/10 to-blue-600/20 hover:from-blue-600/30 hover:to-blue-600/30 text-blue-300 border border-blue-500/40 font-bold text-xs rounded-xl transition-all flex items-center justify-center space-x-2 shadow-sm';
    } else {
      instantSrcBtn.className = 'w-full py-2.5 px-3 bg-gradient-to-r from-emerald-600/20 via-emerald-500/10 to-emerald-600/20 hover:from-emerald-600/30 hover:to-emerald-600/30 text-emerald-300 border border-emerald-500/40 font-bold text-xs rounded-xl transition-all flex items-center justify-center space-x-2 shadow-sm';
    }
  }

  // Update Modal Source Credits Text
  const creditElem = document.getElementById('dl-modal-credit-text');
  if (creditElem) {
    creditElem.innerHTML = file.brand === 'Samsung' 
      ? `Official Samsung 4-File Repair TAR repository powered by <a href="https://samfw.com" target="_blank" rel="noopener noreferrer" class="text-blue-400 font-bold underline">SamFw.com</a>. High-speed local caching maintained by Bhuwan Bastola (Gopal Electronics).`
      : `Official Scatter and PAC firmware archives powered by <a href="https://firmwarefile.com" target="_blank" rel="noopener noreferrer" class="text-emerald-400 font-bold underline">FirmwareFile.com</a>. High-speed local caching maintained by Bhuwan Bastola (Gopal Electronics).`;
  }

  const timerContainer = document.getElementById('dl-timer-container');
  const readyContainer = document.getElementById('dl-ready-container');
  const secondsElem = document.getElementById('dl-seconds-text');
  const badgeElem = document.getElementById('dl-countdown-badge');

  timerContainer.classList.remove('hidden');
  readyContainer.classList.add('hidden');

  let secondsLeft = 5;
  secondsElem.textContent = secondsLeft;
  badgeElem.textContent = secondsLeft + ' seconds';

  const adminBypassContainer = document.getElementById('dl-admin-bypass-container');
  if (adminBypassContainer) {
    if (currentUser && currentUser.role === 'admin') {
      adminBypassContainer.innerHTML = `
        <button onclick="triggerFileDownload(1); closeDownloadModal();" class="mt-2 inline-flex items-center space-x-1 text-[11px] text-amber-400 hover:text-amber-300 font-mono underline font-bold">
          <svg class="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>
          <span>Admin VIP: Skip 5s & Download Immediately</span>
        </button>
      `;
      adminBypassContainer.classList.remove('hidden');
    } else {
      adminBypassContainer.innerHTML = '';
      adminBypassContainer.classList.add('hidden');
    }
  }

  if (countdownInterval) clearInterval(countdownInterval);

  countdownInterval = setInterval(() => {
    secondsLeft--;
    if (secondsLeft > 0) {
      secondsElem.textContent = secondsLeft;
      badgeElem.textContent = secondsLeft + ' seconds';
    } else {
      clearInterval(countdownInterval);
      timerContainer.classList.add('hidden');
      readyContainer.classList.remove('hidden');
      file.downloads = (file.downloads || 0) + 1;
      renderCatalogPage();
      showToast(`5-second verification complete! Starting download for ${file.title}...`);
      triggerFileDownload(1);
    }
  }, 1000);

  modal.classList.remove('hidden');
}

function closeDownloadModal() {
  document.getElementById('download-modal').classList.add('hidden');
  if (countdownInterval) clearInterval(countdownInterval);
}

function copyModalHash() {
  const hash = document.getElementById('dl-modal-hash').textContent;
  navigator.clipboard.writeText(hash).then(() => {
    showToast('SHA256 Checksum copied!');
  }).catch(() => {
    showToast('Hash: ' + hash);
  });
}

