// ================= ADD CUSTOM FILE MODAL =================
function openAddCustomFileModal() {
  const user = getCurrentUser();
  if (!user || user.role !== 'admin') {
    showToast('Access Denied: Only Master Admin can add custom firmware files.');
    openAuthModal('login', 'Administrator Access Required: Please sign in as Admin to add files.');
    return;
  }
  document.getElementById('add-file-modal').classList.remove('hidden');
}

function closeAddCustomFileModal() {
  document.getElementById('add-file-modal').classList.add('hidden');
}

function handleAddCustomFileSubmit(e) {
  e.preventDefault();
  const user = getCurrentUser();
  if (!user || user.role !== 'admin') {
    showToast('Unauthorized: Only Administrator can add files to the database.');
    closeAddCustomFileModal();
    return;
  }
  const title = document.getElementById('add-title').value.trim();
  const brand = document.getElementById('add-brand').value;
  const chipset = document.getElementById('add-chipset').value;
  const category = document.getElementById('add-category').value;
  const size = document.getElementById('add-size').value.trim();
  const target = document.getElementById('add-target').value.trim();
  const url = document.getElementById('add-url').value.trim();
  const source = document.getElementById('add-source').value.trim();
  const desc = document.getElementById('add-desc').value.trim();

  const newFile = {
    id: 'gsm-cust-' + Date.now(),
    title: title,
    brand: brand,
    targetModel: target,
    chipset: chipset,
    category: category,
    fileSize: size,
    accessLevel: 'Free',
    directUrl: url,
    sourceName: source || 'GSM Fix Hub',
    sourceUrl: url.startsWith('http') ? url : '#',
    version: 'Custom Build',
    description: desc,
    checksum: 'sha256_' + Date.now().toString(16) + 'usercustom',
    downloads: 1
  };

  MEGA_DB.unshift(newFile);

  const custom = localStorage.getItem('gsm_custom_files_db');
  let customList = [];
  if (custom) {
    try { customList = JSON.parse(custom); } catch(e) {}
  }
  customList.unshift(newFile);
  localStorage.setItem('gsm_custom_files_db', JSON.stringify(customList));

  const topCount = document.getElementById('top-total-files-count');
  if (topCount) topCount.textContent = MEGA_DB.length.toLocaleString();
  const badge = document.getElementById('badge-total-files');
  if (badge) badge.textContent = MEGA_DB.length.toLocaleString() + ' Files Indexed';
  
  closeAddCustomFileModal();
  renderCatalogPage();
  showToast('New file successfully added to your repair catalog!');
}

// ================= TOAST NOTIFICATION =================
function showToast(msg) {
  const prev = document.getElementById('gsm-toast');
  if (prev && typeof prev.remove === 'function') prev.remove();

  const toast = document.createElement('div');
  toast.id = 'gsm-toast';
  toast.className = 'fixed bottom-5 right-5 z-50 bg-slate-900 border border-cyan-500 text-white text-xs font-medium px-4 py-3 rounded-xl shadow-2xl flex items-center space-x-2 transition-all';
  toast.innerHTML = `
    <svg class="w-4 h-4 text-cyan-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 14 14"></polyline></svg>
    <span>${msg}</span>
  `;
  document.body.appendChild(toast);

  setTimeout(() => {
    if (toast && toast.style) toast.style.opacity = '0';
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}


