// INITIALIZATION ON DOM CONTENT LOADED
// ==========================================
window.addEventListener('DOMContentLoaded', () => {
  loadCustomFilesFromStorage();
  initAuthSession();
  renderHomeFeatured();
  renderTestPoints();
  renderDiagnosticErrors();
  renderSubSeriesPills('All');
  renderCatalogPage();
  renderProcessorTools('all');
  renderFrpTools();
  renderVideoCatalog();

    // Hash Route Guard & Deep-Linking
  function handleHashRoute() {
    const hash = window.location.hash.replace('#', '');
    const user = getCurrentUser();

    if (hash === 'login' || hash === 'signin') {
      openAuthModal('login');
      navigateTo('home');
      return;
    }
    if (hash === 'register') {
      openAuthModal('register');
      navigateTo('home');
      return;
    }
    if (['admin', 'admin-panel'].includes(hash)) {
      if (!user || user.role !== 'admin') {
        showToast('Access Denied: Please sign in as Administrator.');
        openAuthModal('login', 'Admin Access Required: Sign in to access Admin Console.');
        navigateTo('home');
        return;
      }
      navigateTo('admin');
      return;
    }
    if (['flashing-tools', 'frp-bypass'].includes(hash) && !user) {
      showToast('Technician login required to access tools.');
      openAuthModal('login', 'Technician Session Required: Please sign in to access tools.');
      navigateTo('home');
      return;
    }
    if (hash.startsWith('flash-files')) {
      navigateTo('flash-files');
      checkAndApplyAutoFilter();
      return;
    }
    if (['home', 'flash-files', 'drivers', 'flashing-tools', 'frp-bypass', 'video-tutorials', 'admin', 'testpoints'].includes(hash)) {
      navigateTo(hash);
    } else {
      navigateTo('home');
    }
  }

  window.addEventListener('hashchange', handleHashRoute);
  handleHashRoute();});
function openAuthModal(tab = "login", msg = null) {
  const modal = document.getElementById("auth-modal");
  if (!modal) return;
  modal.classList.remove("hidden");

  const contextMsg = document.getElementById("auth-context-msg");
  if (contextMsg) {
    if (msg) {
      contextMsg.textContent = msg;
      contextMsg.classList.remove("hidden");
    } else {
      contextMsg.classList.add("hidden");
    }
  }

  switchAuthTab(tab);
}

function closeAuthModal() {
  const modal = document.getElementById("auth-modal");
  if (modal) modal.classList.add("hidden");
  const errLogin = document.getElementById("login-error-msg");
  if (errLogin) errLogin.classList.add("hidden");
  const errReg = document.getElementById("reg-error-msg");
  if (errReg) errReg.classList.add("hidden");
}

function switchAuthTab(tab) {
  const loginTabBtn = document.getElementById("auth-tab-login");
  const regTabBtn = document.getElementById("auth-tab-register");
  const dbTabBtn = document.getElementById("auth-tab-db");
  const loginForm = document.getElementById("login-form");
  const regForm = document.getElementById("register-form");
  const dbView = document.getElementById("auth-db-view");
  const title = document.getElementById("auth-modal-title");
  const subtitle = document.getElementById("auth-modal-subtitle");

  const errLogin = document.getElementById("login-error-msg");
  if (errLogin) errLogin.classList.add("hidden");
  const errReg = document.getElementById("reg-error-msg");
  if (errReg) errReg.classList.add("hidden");

  const user = getCurrentUser();

  if (tab === "login") {
    if (loginTabBtn) loginTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-cyan-400 text-cyan-400 text-center transition-colors";
    if (regTabBtn) regTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (dbTabBtn) dbTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (loginForm) loginForm.classList.remove("hidden");
    if (regForm) regForm.classList.add("hidden");
    if (dbView) dbView.classList.add("hidden");
    if (title) title.textContent = "Technician Portal Sign In";
    if (subtitle) subtitle.textContent = "Enter your Technician ID or Email and password";
  } else if (tab === "register") {
    if (regTabBtn) regTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-emerald-400 text-emerald-400 text-center transition-colors";
    if (loginTabBtn) loginTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (dbTabBtn) dbTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (regForm) regForm.classList.remove("hidden");
    if (loginForm) loginForm.classList.add("hidden");
    if (dbView) dbView.classList.add("hidden");
    if (title) title.textContent = "Register New Technician Account";
    if (subtitle) subtitle.textContent = "Create your verified account for instant file downloads";
  } else if (tab === "db") {
    if (!user || user.role !== "admin") {
      showToast("Administrator privileges required to view database records.");
      switchAuthTab("login");
      return;
    }
    if (dbTabBtn) dbTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-purple-400 text-purple-400 text-center transition-colors";
    if (loginTabBtn) loginTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (regTabBtn) regTabBtn.className = "flex-1 py-2 text-xs font-bold border-b-2 border-transparent text-slate-400 hover:text-slate-200 text-center transition-colors";
    if (dbView) dbView.classList.remove("hidden");
    if (loginForm) loginForm.classList.add("hidden");
    if (regForm) regForm.classList.add("hidden");
    if (title) title.textContent = "Technician User Database";
    if (subtitle) subtitle.textContent = "Master Administrator view of stored technician accounts";
    renderUsersDbList();
  }
}


